#include "BodyRuntime.hpp"
namespace elysium::medical {bool BodyRuntime::registerPart(BodyPartDef p){return p.id&&parts_.emplace(p.id,p).second;}bool BodyRuntime::addBody(BodyState b,std::string&w){if(!b.owner){w="invalid body";return false;}if(!bodies_.emplace(b.owner,std::move(b)).second){w="duplicate body";return false;}return true;}bool BodyRuntime::addWound(StableId id,Wound x,std::string&w){auto b=bodies_.find(id);if(b==bodies_.end()||!parts_.count(x.part)){w="unknown body/part";return false;}x.severity=std::clamp(std::isfinite(x.severity)?x.severity:0.0,0.0,1.0);b->second.wounds.push_back(x);b->second.vitals.pain=std::clamp(b->second.vitals.pain+x.pain,0.0,1.0);b->second.vitals.blood=std::clamp(b->second.vitals.blood-x.bleeding,0.0,1.0);return true;}double BodyRuntime::capability(StableId id,std::uint32_t tag)const{auto b=bodies_.find(id);if(b==bodies_.end())return 0;double c=1;for(auto&w:b->second.wounds){auto p=parts_.find(w.part);if(p!=parts_.end()&&(p->second.functionTags&tag)){if(w.missing)return 0;c*=1.0-w.severity;}}return std::clamp(c,0.0,1.0);}std::optional<BodyState>BodyRuntime::get(StableId id)const{auto i=bodies_.find(id);if(i==bodies_.end())return std::nullopt;return i->second;}}
